import { z } from 'zod';
export const Point3DSchema = z.object({ x: z.number(), y: z.number(), z: z.number() });
export const MacroNutrientsSchema = z.object({ caloriesKcal: z.number().nonnegative(), carbsG: z.number().nonnegative(), proteinG: z.number().nonnegative(), fatG: z.number().nonnegative(), sodiumMg: z.number().nonnegative() });
export const SparsePointCloudSchema = z.object({ count: z.number().int().min(0).max(5000), positions: z.array(z.number()), colors: z.array(z.number()) }).superRefine((v, c) => { if (v.positions.length !== v.count * 3)
    c.addIssue({ code: 'custom', message: 'positions length must equal count * 3' }); if (v.colors.length !== v.count * 3)
    c.addIssue({ code: 'custom', message: 'colors length must equal count * 3' }); });
const Candidate = z.object({ foodId: z.string().min(1), foodName: z.string().min(1), score: z.number(), densityGCm3: z.number().nullable().optional(), weightG: z.number().nullable().optional(), caloriesKcal: z.number().nullable().optional(), carbsG: z.number().nullable().optional(), proteinG: z.number().nullable().optional(), fatG: z.number().nullable().optional(), sodiumMg: z.number().nullable().optional() });
export const BoundingBox2DSchema = z.object({ ymin: z.number(), xmin: z.number(), ymax: z.number(), xmax: z.number() });
export const BoundingBox3DSchema = z.object({ center: Point3DSchema, dimensions: Point3DSchema, rotations: Point3DSchema, vertices: z.array(Point3DSchema) });
export const FoodItemEstimationSchema = z.object({ id: z.string().min(1), foodId: z.string().min(1), foodName: z.string().min(1), confidenceScore: z.number(), classificationConfidence: z.number(), geometryConfidence: z.number(), requiresConfirmation: z.boolean(), topCandidates: z.array(Candidate), volumeCm3: z.number().positive(), densityGCm3: z.number().positive(), weightG: z.number().positive(), caloriesKcal: z.number().nonnegative(), carbsG: z.number().nonnegative(), proteinG: z.number().nonnegative(), fatG: z.number().nonnegative(), sodiumMg: z.number().nonnegative(), bbox2d: BoundingBox2DSchema, bbox3d: BoundingBox3DSchema });
export const DrugInteractionWarningSchema = z.object({ id: z.string(), drugBrandName: z.string(), drugIngredient: z.string(), triggerNutrientOrFood: z.string(), riskLevel: z.string(), detectedVia: z.string(), warningTitle: z.string(), warningMessage: z.string(), actionGuide: z.string() });
export const DetectedPillInputSchema = z.object({ class_name: z.string(), class_id: z.number().nullable().optional(), confidence: z.number().nullable().optional(), box: z.array(z.number()).nullable().optional() });
export const NutritionSummarySchema = MacroNutrientsSchema;
export const PlaneEquationSchema = z.object({ a: z.number(), b: z.number(), c: z.number(), d: z.number() });
export const Visualization3DSchema = z.object({ pointCloud: SparsePointCloudSchema });
export const MealEstimateResponseSchema = z.object({ mealId: z.string().min(1), isPersisted: z.boolean(), requiresConfirmation: z.boolean(), imageUrl: z.string().min(1), isCalibrated: z.boolean(), focalLengthMm: z.number().positive(), groundPlane: PlaneEquationSchema, totalNutrition: MacroNutrientsSchema, foodItems: z.array(FoodItemEstimationSchema), drugWarnings: z.array(DrugInteractionWarningSchema).default([]), detectedPills: z.array(DetectedPillInputSchema).optional(), visualization3d: Visualization3DSchema, processedAt: z.string().datetime(), inferenceLatencyMs: z.number().nonnegative() });
export const MealConfirmRequestSchema = z.object({ mealId: z.string().min(1), corrections: z.array(z.object({ foodItemId: z.string().min(1), correctedWeightG: z.number().positive() })) });
